use std::time::Duration;

/// Run `n` simulated fetches CONCURRENTLY (each takes ~100ms) and return
/// their results in task order.
pub async fn fetch_all(n: usize) -> Vec<u64> {
    let mut handles = Vec::new();
    for i in 0..n {
        handles.push(tokio::spawn(async move {
            // BUG: std::thread::sleep BLOCKS the runtime worker thread -
            // tasks serialize onto the worker pool instead of overlapping.
            std::thread::sleep(Duration::from_millis(100));
            (i as u64) * 2
        }));
    }
    let mut out = Vec::new();
    for h in handles {
        out.push(h.await.unwrap());
    }
    out
}

