use conc_case::fetch_all;
use std::time::Instant;

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn tasks_overlap() {
    let start = Instant::now();
    let out = fetch_all(8).await;
    let elapsed = start.elapsed();

    assert_eq!(out, vec![0, 2, 4, 6, 8, 10, 12, 14], "results/order wrong: {:?}", out);
    // blocking sleeps serialize onto 2 workers: >= 400ms. Async sleeps: ~100ms.
    assert!(
        elapsed.as_millis() < 250,
        "8 concurrent 100ms tasks took {:?} - still blocking the runtime",
        elapsed
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn empty_is_fine() {
    assert!(fetch_all(0).await.is_empty());
}

