use std::time::Duration;

pub async fn fetch_all(n: usize) -> Vec<u64> {
    // tokio::time::sleep, but awaited one after another - no concurrency
    let mut out = Vec::new();
    for i in 0..n {
        tokio::time::sleep(Duration::from_millis(100)).await;
        out.push((i as u64) * 2);
    }
    out
}
